package com.example.payment.unittest.architecture;

import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noClasses;

import com.tngtech.archunit.core.domain.JavaClasses;
import com.tngtech.archunit.core.importer.ClassFileImporter;
import com.tngtech.archunit.core.importer.ImportOption;
import org.junit.jupiter.api.Test;

/**
 * Guards the layering of the business code: domain and application classes must stay free of
 * technical/infrastructure detail (HTTP clients, JSON libraries, JDBC, frameworks, ...).
 *
 * <p>This only imports the classes already on this module's classpath (domain + application), so
 * it runs as part of the everyday unit test suite and stays fast - no infrastructure jar, no
 * Spring context, no extra classpath scanning is involved.
 */
class LayeringTest {

    private static final JavaClasses BUSINESS_CLASSES =
            new ClassFileImporter()
                    .withImportOption(ImportOption.Predefined.DO_NOT_INCLUDE_TESTS)
                    .importPackages("com.example.payment.domain", "com.example.payment.application");

    @Test
    void domain_does_not_depend_on_application_or_infrastructure() {
        noClasses()
                .that().resideInAPackage("com.example.payment.domain..")
                .should().dependOnClassesThat()
                .resideInAnyPackage("com.example.payment.application..", "com.example.payment.infrastructure..")
                .check(BUSINESS_CLASSES);
    }

    @Test
    void business_code_does_not_depend_on_the_infrastructure_layer() {
        noClasses()
                .that().resideInAnyPackage("com.example.payment.domain..", "com.example.payment.application..")
                .should().dependOnClassesThat()
                .resideInAPackage("com.example.payment.infrastructure..")
                .check(BUSINESS_CLASSES);
    }

    @Test
    void business_code_does_not_leak_technical_details() {
        noClasses()
                .that().resideInAnyPackage("com.example.payment.domain..", "com.example.payment.application..")
                .should().dependOnClassesThat()
                .resideInAnyPackage(
                        "org.springframework..",
                        "com.fasterxml.jackson..",
                        "java.sql..",
                        "javax.persistence..",
                        "jakarta.persistence..")
                .check(BUSINESS_CLASSES);
    }
}

